function replaceHyphen(
  _match: string,
  from: string,
  fM: string,
  fm: string,
  fp: string,
  fpr: string,
  _fb: string,
  to: string,
  tM: string,
  tm: string,
  tp: string,
  tpr: string,
): string {
  let lower: string;
  if (isX(fM)) lower = "";
  else if (isX(fm)) lower = `>=${fM}.0.0`;
  else if (isX(fp)) lower = `>=${fM}.${fm}.0`;
